script.source:
return ['_doc': ctx.payload.hits.hits.stream().map(
        v -> {v.get('_source').put('index', v.get('_index'));
        v.remove('_index');
        v.remove('_type');
        v.get('_source').put('threat.detection', ctx.watch_id);
        v.get('_source').put('threat.framework', 'MITRE ATT&CK');
        v.get('_source').put('threat.technique.id', 'T1567');
        v.get('_source').put('threat.technique.name', 'Exfiltration Over Web Service');
        v.get('_source').put('threat.technique.reference', 'https://attack.mitre.org/techniques/T1567');
        v.get('_source').put('threat.tactic.id', 'TA0010, TA0011');
        v.get('_source').put('threat.tactic.name', 'Exfiltration, Command and Control');
        v.get('_source').put('threat.tactic.reference', 'https://attack.mitre.org/tactics/TA0010, https://attack.mitre.org/tactics/TA0011');
        v.get('_source').put('event.timestamp_detected', ctx.trigger.triggered_time);
        v.get('_source').put('threat.is_alert', true);
        v.get('_source').put('threat.alert_type', 'Detection of Exfiltration Attack');
        v.get('_source').put('threat.detection_description', 'AWS Guardduty detects any exfiltration related attacks such as IAM entity invoked an S3 API in a suspicious way.');
        v.get('_source').put('threat.severity', 'medium');
        v.get('_source').put('threat.triage_score', 40);
        v.get('_source').put('threat.ratingtime_sla_applies', 'true');
        v.get('_source').put('id', v.get('_id'));
        return v.get('_source')}).collect(Collectors.toList())]
